import React, { useState, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import { ProductsContext } from '../context/ProductsContext';
import { CartContext } from '../context/CartContext';
import { FiPlus, FiMinus, FiCheck } from 'react-icons/fi';
import toast from 'react-hot-toast';
import './BouquetBuilder.css';

const BouquetBuilder = () => {
  const navigate = useNavigate();
  const { products, packages, ribbons } = useContext(ProductsContext);
  const { addToCart } = useContext(CartContext);

  // Состояния для конструктора
  const [selectedFlowers, setSelectedFlowers] = useState([]);
  const [selectedPackage, setSelectedPackage] = useState(null);
  const [selectedRibbon, setSelectedRibbon] = useState(null);
  const [cardText, setCardText] = useState('');
  const [cardSignature, setCardSignature] = useState('');
  const [deliveryAddress, setDeliveryAddress] = useState({
    street: '',
    house: '',
    apartment: '',
    entrance: '',
    floor: '',
    comment: ''
  });

  // Подсчёт стоимости
  const flowersPrice = selectedFlowers.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const packagePrice = selectedPackage?.price || 0;
  const ribbonPrice = selectedRibbon?.price || 0;
  const totalPrice = flowersPrice + packagePrice + ribbonPrice;

  // Добавление цветка в конструктор
  const addFlower = (flower) => {
    const existing = selectedFlowers.find(f => f.id === flower.id);
    if (existing) {
      setSelectedFlowers(selectedFlowers.map(f =>
        f.id === flower.id ? { ...f, quantity: f.quantity + 1 } : f
      ));
    } else {
      setSelectedFlowers([...selectedFlowers, { ...flower, quantity: 1 }]);
    }
  };

  const removeFlower = (flowerId) => {
    setSelectedFlowers(selectedFlowers.filter(f => f.id !== flowerId));
  };

  const updateQuantity = (flowerId, newQuantity) => {
    if (newQuantity <= 0) {
      removeFlower(flowerId);
    } else {
      setSelectedFlowers(selectedFlowers.map(f =>
        f.id === flowerId ? { ...f, quantity: newQuantity } : f
      ));
    }
  };

  const handleAddToCart = () => {
    if (selectedFlowers.length === 0) {
      toast.error('Выберите хотя бы один цветок!');
      return;
    }
    if (!selectedPackage) {
      toast.error('Выберите упаковку!');
      return;
    }
    if (!selectedRibbon) {
      toast.error('Выберите ленту!');
      return;
    }
    if (!deliveryAddress.street || !deliveryAddress.house) {
      toast.error('Укажите адрес доставки!');
      return;
    }

    // Создаём объект букета
    const bouquetItem = {
      id: `bouquet_${Date.now()}`,
      type: 'bouquet',
      name: 'Собранный букет',
      flowers: selectedFlowers.map(f => ({ name: f.name, quantity: f.quantity, price: f.price })),
      package: selectedPackage,
      ribbon: selectedRibbon,
      card: { text: cardText, signature: cardSignature },
      deliveryAddress,
      price: totalPrice,
      quantity: 1,
      imageUrl: selectedFlowers[0]?.imageUrl || 'https://via.placeholder.com/300'
    };

    addToCart(bouquetItem);
    toast.success('Букет добавлен в корзину!');
    navigate('/cart');
  };

  return (
    <div className="bouquet-builder">
      <h1 className="builder-title">🌸 Собери свой букет</h1>

      <div className="builder-layout">
        {/* Левая колонка - выбор цветов */}
        <div className="builder-section flowers-section">
          <h2>1. Выберите цветы</h2>
          <div className="flowers-grid">
            {products.map(flower => (
              <div key={flower.id} className="flower-item" onClick={() => addFlower(flower)}>
                <img src={flower.imageUrl} alt={flower.name} className="flower-image" />
                <div className="flower-info">
                  <span className="flower-name">{flower.name}</span>
                  <span className="flower-price">{flower.price} ₸</span>
                </div>
                <button className="add-flower-btn"><FiPlus /></button>
              </div>
            ))}
          </div>

          {/* Выбранные цветы */}
          {selectedFlowers.length > 0 && (
            <div className="selected-flowers">
              <h3>Выбранные цветы:</h3>
              {selectedFlowers.map(flower => (
                <div key={flower.id} className="selected-flower">
                  <span>{flower.name}</span>
                  <div className="quantity-control">
                    <button onClick={() => updateQuantity(flower.id, flower.quantity - 1)}><FiMinus /></button>
                    <span>{flower.quantity}</span>
                    <button onClick={() => updateQuantity(flower.id, flower.quantity + 1)}><FiPlus /></button>
                  </div>
                  <span className="flower-subtotal">{flower.price * flower.quantity} ₸</span>
                  <button className="remove-flower" onClick={() => removeFlower(flower.id)}>✕</button>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Средняя колонка - упаковка и лента */}
        <div className="builder-section options-section">
          <h2>2. Выберите упаковку</h2>
          <div className="options-grid">
            {packages.map(pkg => (
              <div
                key={pkg.id}
                className={`option-card ${selectedPackage?.id === pkg.id ? 'selected' : ''}`}
                onClick={() => setSelectedPackage(pkg)}
              >
                <img src={pkg.image} alt={pkg.name} className="option-image" />
                <span className="option-name">{pkg.name}</span>
                <span className="option-price">{pkg.price} ₸</span>
                {selectedPackage?.id === pkg.id && <FiCheck className="check-icon" />}
              </div>
            ))}
          </div>

          <h2>3. Выберите ленту</h2>
          <div className="options-grid">
            {ribbons.map(rib => (
              <div
                key={rib.id}
                className={`option-card ${selectedRibbon?.id === rib.id ? 'selected' : ''}`}
                onClick={() => setSelectedRibbon(rib)}
                style={{ borderColor: rib.color }}
              >
                <div className="ribbon-preview" style={{ background: rib.color }}></div>
                <span className="option-name">{rib.name}</span>
                <span className="option-price">{rib.price} ₸</span>
                {selectedRibbon?.id === rib.id && <FiCheck className="check-icon" />}
              </div>
            ))}
          </div>
        </div>

        {/* Правая колонка - открытка, адрес и итог */}
        <div className="builder-section details-section">
          <h2>4. Открытка (необязательно)</h2>
          <textarea
            placeholder="Текст на открытке..."
            value={cardText}
            onChange={(e) => setCardText(e.target.value)}
            className="card-input"
          />
          <input
            type="text"
            placeholder="Подпись (от кого)"
            value={cardSignature}
            onChange={(e) => setCardSignature(e.target.value)}
            className="signature-input"
          />

          <h2>5. Адрес доставки</h2>
          <div className="address-grid">
            <input
              type="text"
              placeholder="Улица *"
              value={deliveryAddress.street}
              onChange={(e) => setDeliveryAddress({...deliveryAddress, street: e.target.value})}
              required
            />
            <input
              type="text"
              placeholder="Дом *"
              value={deliveryAddress.house}
              onChange={(e) => setDeliveryAddress({...deliveryAddress, house: e.target.value})}
              required
            />
            <input
              type="text"
              placeholder="Квартира"
              value={deliveryAddress.apartment}
              onChange={(e) => setDeliveryAddress({...deliveryAddress, apartment: e.target.value})}
            />
            <input
              type="text"
              placeholder="Подъезд"
              value={deliveryAddress.entrance}
              onChange={(e) => setDeliveryAddress({...deliveryAddress, entrance: e.target.value})}
            />
            <input
              type="text"
              placeholder="Этаж"
              value={deliveryAddress.floor}
              onChange={(e) => setDeliveryAddress({...deliveryAddress, floor: e.target.value})}
            />
            <textarea
              placeholder="Комментарий курьеру"
              value={deliveryAddress.comment}
              onChange={(e) => setDeliveryAddress({...deliveryAddress, comment: e.target.value})}
              className="full-width"
            />
          </div>

          <div className="builder-total">
            <div className="total-line">
              <span>Цветы:</span>
              <span>{flowersPrice} ₸</span>
            </div>
            <div className="total-line">
              <span>Упаковка:</span>
              <span>{packagePrice} ₸</span>
            </div>
            <div className="total-line">
              <span>Лента:</span>
              <span>{ribbonPrice} ₸</span>
            </div>
            <div className="total-line final">
              <span>Итого:</span>
              <span>{totalPrice} ₸</span>
            </div>
          </div>

          <button className="add-to-cart-builder" onClick={handleAddToCart}>
            Добавить в корзину
          </button>
        </div>
      </div>
    </div>
  );
};

export default BouquetBuilder;